import { QuizCardProps } from '../types';

const optionLabels = ['A', 'B', 'C', 'D'];

const QuizCard = ({
  question,
  questionIndex,
  totalQuestions,
  onAnswer,
  onNext,
  selectedAnswerIndex,
  isAnswered,
}: QuizCardProps) => {
  const isCorrect = selectedAnswerIndex !== null && selectedAnswerIndex === question.answerIndex;

  const getOptionClassName = (index: number) => {
    const base = 'option-btn';

    if (!isAnswered) {
      if (selectedAnswerIndex === index) {
        return `${base} selected`;
      }
      return base;
    }

    if (index === question.answerIndex) {
      return `${base} correct disabled`;
    }

    if (index === selectedAnswerIndex) {
      return `${base} incorrect disabled`;
    }

    return `${base} disabled`;
  };

  const handleOptionClick = (index: number) => {
    if (isAnswered) {
      return;
    }
    onAnswer?.(index);
  };

  return (
    <div className="card">
      <span className="question-badge">
        第 {questionIndex + 1} 問 / 全 {totalQuestions} 問
      </span>

      <h2 className="question-text">{question.question}</h2>

      <div className="options-grid">
        {question.options.map((option, index) => (
          <button
            key={index}
            type="button"
            className={getOptionClassName(index)}
            onClick={() => handleOptionClick(index)}
            disabled={isAnswered}
          >
            <span className="option-badge">{optionLabels[index]}</span>
            <span className="option-text">{option}</span>
          </button>
        ))}
      </div>

      {isAnswered && (
        <div className="feedback-panel">
          <div className={`feedback-status ${isCorrect ? 'correct' : 'incorrect'}`}>
            {isCorrect ? '正解！⭕' : '不正解…❌'}
          </div>
          <p className="feedback-text">{question.explanation}</p>
          <button
            type="button"
            className="next-btn"
            onClick={() => onNext?.()}
          >
            {questionIndex + 1 < totalQuestions ? '次の問題へ進む' : '結果を見る'}
          </button>
        </div>
      )}
    </div>
  );
};

export default QuizCard;

import { ResultCardProps } from '../types';

const getRankInfo = (score: number, total: number) => {
  if (score === total) {
    return {
      title: '🏆 日本地理マスター！',
      desc: '素晴らしい！全問正解達成です。日本の地理について完璧な知識を持っています！',
    };
  }
  if (score >= 4) {
    return {
      title: '🌟 日本地理エキスパート！',
      desc: '惜しくも満点は逃したものの、極めて高い地理の知識を持っています！',
    };
  }
  if (score >= 3) {
    return {
      title: '👍 日本地理チャレンジャー！',
      desc: 'ナイスファイト！基礎知識はしっかり身についています。次は満点を目指しましょう！',
    };
  }
  return {
    title: '🌱 これから覚える旅人！',
    desc: '日本にはまだまだ面白い地理の秘密がたくさんあります。復習して再挑戦してみましょう！',
  };
};

const ResultCard = ({
  score = 0,
  totalQuestions = 5,
  answers = [],
  questions = [],
  onRetry,
}: ResultCardProps) => {
  const rank = getRankInfo(score, totalQuestions);

  return (
    <div className="result-card">
      <div className="result-header">
        <div className="result-score-box">
          <span className="result-score-num">{score}</span>
          <span className="result-score-total">/{totalQuestions}</span>
        </div>
        <h2 className="result-rank-title">{rank.title}</h2>
        <p className="result-rank-desc">{rank.desc}</p>
      </div>

      <div className="review-section">
        <h3 className="review-title">📝 問題の振り返り</h3>
        <div className="review-list">
          {questions.map((q, idx) => {
            const userAnswer = answers.find((ans) => ans.questionId === q.id);
            const isUserCorrect = userAnswer?.isCorrect ?? false;
            const userChoiceText =
              userAnswer !== undefined && userAnswer.selectedIndex >= 0
                ? q.options[userAnswer.selectedIndex]
                : '未回答';
            const correctChoiceText = q.options[q.answerIndex];

            return (
              <div
                key={q.id}
                className={`review-item ${isUserCorrect ? 'correct' : 'incorrect'}`}
              >
                <div className="review-q-title">
                  問{idx + 1}. {q.question}
                </div>
                <div className="review-ans-row">
                  <span>
                    あなたの回答: <strong>{userChoiceText}</strong> ({isUserCorrect ? '⭕ 正解' : '❌ 不正解'})
                  </span>
                  {!isUserCorrect && (
                    <span>
                      正解: <strong>{correctChoiceText}</strong>
                    </span>
                  )}
                </div>
                <p className="feedback-text">{q.explanation}</p>
              </div>
            );
          })}
        </div>
      </div>

      <button
        type="button"
        className="retry-btn"
        onClick={() => onRetry?.()}
      >
        もう一度挑戦する
      </button>
    </div>
  );
};

export default ResultCard;

import { useState } from 'react';
import { quizQuestions } from './data/quizData';
import { UserAnswer } from './types';
import QuizCard from './components/QuizCard';
import ResultCard from './components/ResultCard';
import './index.css';

const App = () => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState<number>(0);
  const [selectedAnswerIndex, setSelectedAnswerIndex] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState<boolean>(false);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [isFinished, setIsFinished] = useState<boolean>(false);

  const totalQuestions = quizQuestions.length;
  const currentQuestion = quizQuestions[currentQuestionIndex];

  const handleAnswer = (selectedIndex: number) => {
    if (isAnswered) {
      return;
    }

    const isCorrect = selectedIndex === currentQuestion.answerIndex;
    setSelectedAnswerIndex(selectedIndex);
    setIsAnswered(true);

    const newAnswer: UserAnswer = {
      questionId: currentQuestion.id,
      selectedIndex,
      isCorrect,
    };

    setUserAnswers((prev) => [...prev, newAnswer]);
  };

  const handleNext = () => {
    if (currentQuestionIndex + 1 < totalQuestions) {
      setCurrentQuestionIndex((prev) => prev + 1);
      setSelectedAnswerIndex(null);
      setIsAnswered(false);
    } else {
      setIsFinished(true);
    }
  };

  const handleRetry = () => {
    setCurrentQuestionIndex(0);
    setSelectedAnswerIndex(null);
    setIsAnswered(false);
    setUserAnswers([]);
    setIsFinished(false);
  };

  const score = userAnswers.filter((ans) => ans.isCorrect).length;
  const progressPercent = isFinished
    ? 100
    : Math.round(((currentQuestionIndex + (isAnswered ? 1 : 0)) / totalQuestions) * 100);

  return (
    <div className="quiz-app">
      <header className="quiz-header">
        <h1 className="quiz-title">🗾 日本地理クイズ</h1>
        <p className="quiz-subtitle">全5問で地理の豆知識を試してみよう！</p>
      </header>

      {!isFinished && (
        <div className="quiz-progress-wrapper">
          <div className="quiz-progress-text">
            <span>
              問題 {currentQuestionIndex + 1} / {totalQuestions}
            </span>
            <span>{progressPercent}% 完了</span>
          </div>
          <div className="quiz-progress-bar-bg">
            <div
              className="quiz-progress-bar-fill"
              style={{ width: `${progressPercent}%` }}
            />
          </div>
        </div>
      )}

      <main>
        {!isFinished ? (
          <QuizCard
            question={currentQuestion}
            questionIndex={currentQuestionIndex}
            totalQuestions={totalQuestions}
            onAnswer={handleAnswer}
            onNext={handleNext}
            selectedAnswerIndex={selectedAnswerIndex}
            isAnswered={isAnswered}
          />
        ) : (
          <ResultCard
            score={score}
            totalQuestions={totalQuestions}
            answers={userAnswers}
            questions={quizQuestions}
            onRetry={handleRetry}
          />
        )}
      </main>
    </div>
  );
};

export default App;
